import { readFileSync, readdirSync, writeFileSync, unlinkSync } from 'node:fs';
import { gzipSync, gunzipSync } from 'node:zlib';
import { dirname, join, resolve, sep } from 'node:path';
import { fileURLToPath } from 'node:url';
const root=dirname(fileURLToPath(import.meta.url));
let files=0, before=0, after=0;
for(const directory of readdirSync(root).filter(name=>name.endsWith('-stages'))) {
  for(const name of readdirSync(join(root,directory)).filter(name=>name.endsWith('.jsonl'))) {
    const file=resolve(root,directory,name);
    if(!file.startsWith(resolve(root)+sep)) throw new Error('Trace outside evidence directory');
    const raw=readFileSync(file), compressed=gzipSync(raw);
    if(!gunzipSync(compressed).equals(raw)) throw new Error('Archive verification failed');
    writeFileSync(file+'.gz',compressed); unlinkSync(file);
    files++;before+=raw.length;after+=compressed.length;
  }
}
console.log(JSON.stringify({files,uncompressed_bytes:before,compressed_bytes:after}));

import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { dirname, join, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
const directory=dirname(fileURLToPath(import.meta.url)),repo=resolve(directory,'../../../../..');
const sha=bytes=>createHash('sha256').update(bytes).digest('hex');
function walk(root) { return readdirSync(root,{withFileTypes:true}).flatMap(entry=>entry.isDirectory()?walk(join(root,entry.name)):[join(root,entry.name)]); }
const files=walk(directory).filter(file=>!file.endsWith('evidence-index.json')).map(file=>{
  const path=relative(repo,file).replaceAll('\\','/'),raw=readFileSync(file);
  const staged=execFileSync('git',['show',':'+path],{cwd:repo,maxBuffer:64*1024*1024});
  return {path,raw_sha256:sha(raw),published_sha256:sha(staged),published_bytes:staged.length};
});
writeFileSync(join(directory,'evidence-index.json'),JSON.stringify({reference:'26143382d1262b2ef9cbeb02f8773148e4439ebc',files},null,2)+'\n');
console.log(JSON.stringify({files:files.length,published_bytes:files.reduce((n,f)=>n+f.published_bytes,0)}));

import { readFileSync, writeFileSync, readdirSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
const root = dirname(fileURLToPath(import.meta.url));
const parse = path => JSON.parse(readFileSync(path, 'utf8').replace(/^\uFEFF/, ''));
function identities(report) {
  return report.testResults.flatMap(file => {
    const seen = new Map();
    return file.assertionResults.map(test => {
      const path = file.name.replaceAll('\\', '/').split('/packages/mcp/').at(-1);
      const ordinal = (seen.get(test.fullName) ?? 0) + 1; seen.set(test.fullName, ordinal);
      return { id: JSON.stringify([path, test.fullName, ordinal]), file: path, fullName: test.fullName, ordinal,
        status: test.status, duration_ms: test.duration, errors: test.failureMessages };
    });
  });
}
const baseline = identities(parse(join(root, '../../VNEXT-014-TEST-MODERNIZATION/evidencia/final-serial.json')));
const base = new Map(baseline.map(row => [row.id, row]));
const results = {};
for (const name of ['before-focal','before-isolated','before-group','before-group-normal','before-full','after-isolated','after-group','after-full','cache-normal-1','browser-debug','lazy-normal-1','lazy-normal-2','final-parallel-1','final-parallel-2','final-serial','final-stages','final-focal']) {
  if (!existsSync(join(root, name+'.json'))) continue;
  const raw = parse(join(root, name+'.json')), rows = identities(raw), keys = new Set(rows.map(row=>row.id));
  const selectedBaseline = baseline.filter(row => rows.some(current => current.file === row.file));
  const log = readFileSync(join(root, name+'.log'), 'utf8');
  results[name] = {
    pass: rows.filter(r=>r.status==='passed').length, fail: rows.filter(r=>r.status==='failed').length,
    pending: rows.filter(r=>!['passed','failed'].includes(r.status)).length, total: rows.length,
    wall_ms: Math.max(...raw.testResults.map(f=>f.endTime))-Math.min(...raw.testResults.map(f=>f.startTime)),
    preserved_pass: rows.filter(row=>row.status==='passed'&&base.get(row.id)?.status==='passed').length,
    historical_failures: rows.filter(row=>row.status==='failed'&&base.get(row.id)?.status==='failed'),
    extra_failures: rows.filter(row=>row.status==='failed'&&base.get(row.id)?.status!=='failed'),
    recovered: rows.filter(row=>row.status==='passed'&&base.get(row.id)?.status==='failed'),
    added: rows.filter(row=>!base.has(row.id)), removed: selectedBaseline.filter(row=>!keys.has(row.id)),
    lifecycle: rows.filter(r=>r.file.endsWith('/lifecycle-v3-e2e.test.ts')),
    testHandler: rows.filter(r=>r.file.endsWith('/test-handler.test.ts')),
    error_lines: log.split(/\r?\n/).filter(line=>/Hook timed out|Test timed out|Unhandled Rejection|Unhandled Error|ECOMPROMISED|ENOENT|SQLITE_BUSY|closed database/.test(line)),
  };
}
writeFileSync(join(root, 'comparison.json'), JSON.stringify(results, null, 2)+'\n');
for (const [name, r] of Object.entries(results)) console.log(name, `${r.pass}/${r.fail}/${r.total}`, 'extra',r.extra_failures.length,'new',r.added.length,'removed',r.removed.length);
const browserRows = new Map();
for (const line of readFileSync(join(root, 'browser-debug.log'),'utf8').split('\n')) {
  const at = Date.parse(line.slice(0,24)), pid = line.match(/\[pid=(\d+)\]/)?.[1];
  if (!pid || !Number.isFinite(at)) continue;
  const row = browserRows.get(pid) ?? { pid };
  for (const [key, text] of [['close_started','gracefully close start'],['process_exited','process did exit'],['profile_removed','finished temporary directories cleanup']]) if (line.includes(text)) row[key]=at;
  browserRows.set(pid,row);
}
writeFileSync(join(root,'browser-shutdown.json'),JSON.stringify([...browserRows.values()].map(row=>({...row,process_exit_ms:row.process_exited-row.close_started,profile_cleanup_ms:row.profile_removed-row.process_exited})),null,2)+'\n');
const host = {};
for (const name of readdirSync(root).filter(n=>n.endsWith('-host.json'))) {
  const rows = parse(join(root,name));
  host[name]={ samples:rows.length,min_available_mb:Math.min(...rows.map(r=>r.available_mb)),max_cpu_percent:Math.max(...rows.map(r=>r.cpu_percent)),max_pages_input_per_sec:Math.max(...rows.map(r=>r.pages_input_per_sec)),max_disk_queue:Math.max(...rows.map(r=>r.disk_queue)) };
}
writeFileSync(join(root,'host-summary.json'), JSON.stringify(host,null,2)+'\n');

import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { gunzipSync } from 'node:zlib';
const root = dirname(fileURLToPath(import.meta.url));
const report = {};
for (const directory of readdirSync(root).filter(name => name.endsWith('-stages'))) {
  const stages = {}, pending = [], samples = [], tests = [];
  for (const file of readdirSync(join(root, directory))) {
    const open = new Map();
    const bytes = readFileSync(join(root, directory, file));
    const contents = file.endsWith('.gz') ? gunzipSync(bytes).toString('utf8') : bytes.toString('utf8');
    for (const line of contents.trim().split('\n')) {
      const event = JSON.parse(line);
      if (event.event === 'begin') open.set(event.id, event);
      if (event.event === 'end') {
        open.delete(event.id);
        const stage = stages[event.stage] ??= { count: 0, total_ms: 0, process_cpu_ms: 0, durations_ms: [], errors: 0 };
        stage.count++; stage.total_ms += event.ms; stage.process_cpu_ms += event.cpu_ms;
        stage.durations_ms.push(event.ms); if (event.error) stage.errors++;
      }
      if (event.event === 'sample') samples.push(event);
      if (event.event.startsWith('test.')) tests.push(event);
    }
    pending.push(...open.values());
  }
  for (const stage of Object.values(stages)) {
    const times = stage.durations_ms.sort((a,b) => a-b);
    stage.p50_ms = times[Math.floor(times.length * .5)]; stage.p95_ms = times[Math.min(times.length-1, Math.floor(times.length*.95))]; stage.max_ms = times.at(-1);
    delete stage.durations_ms;
  }
  report[directory] = { stages, incomplete_spans: pending, sample_count: samples.length, max_event_loop_lag_ms: Math.max(...samples.map(s=>s.lag_ms)), tests };
}
writeFileSync(join(root, 'stage-summary.json'), JSON.stringify(report, null, 2)+'\n');
for (const [name, run] of Object.entries(report)) console.log(name, JSON.stringify(Object.fromEntries(Object.entries(run.stages).filter(([k])=>['schema.compile','schema.validate','chromium.launch','browser.newContext','context.newPage','browser.close','lock.acquire','sqlite.exec','crawler.run','runner.execute'].includes(k)).map(([k,v])=>[k,{n:v.count,total:Math.round(v.total_ms),max:Math.round(v.max_ms)}]))), 'pending', run.incomplete_spans.length);

import ts from '../../../../../node_modules/typescript/lib/typescript.js';
import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
const directory=dirname(fileURLToPath(import.meta.url)), root=resolve(directory,'../../../../..');
const reference='26143382d1262b2ef9cbeb02f8773148e4439ebc';
const config=ts.readConfigFile(resolve(root,'packages/mcp/tsconfig.json'),ts.sys.readFile);
const parsed=ts.parseJsonConfigFileContent(config.config,ts.sys,resolve(root,'packages/mcp'),{noEmit:true},resolve(root,'packages/mcp/tsconfig.json'));
const changed=execFileSync('git',['diff','--name-only',reference,'--','packages/mcp'],{cwd:root,encoding:'utf8'}).trim().split(/\r?\n/).filter(f=>f.endsWith('.ts'));
const oldFiles=new Map(changed.map(file=>{
  let original;
  try { original=execFileSync('git',['show',reference+':'+file],{cwd:root,encoding:'utf8',stdio:['ignore','pipe','ignore']}); } catch { /* New diagnostic/test file did not exist at baseline. */ }
  return [resolve(root,file).toLowerCase(),original];
}));
function check(before) {
  const host=ts.createCompilerHost({...parsed.options,noEmit:true});
  if(before) {
    const read=host.readFile.bind(host),exists=host.fileExists.bind(host);
    host.readFile=file=>oldFiles.has(resolve(file).toLowerCase())?oldFiles.get(resolve(file).toLowerCase()):read(file);
    host.fileExists=file=>oldFiles.has(resolve(file).toLowerCase())?oldFiles.get(resolve(file).toLowerCase())!==undefined:exists(file);
  }
  const program=ts.createProgram(parsed.fileNames.filter(file=>!before||host.fileExists(file)),{...parsed.options,noEmit:true},host);
  return ts.getPreEmitDiagnostics(program).map(d=>({file:d.file?.fileName.replaceAll('\\','/').replace(root.replaceAll('\\','/')+'/',''),code:d.code,message:ts.flattenDiagnosticMessageText(d.messageText,'\n')}));
}
const before=check(true),after=check(false), key=d=>JSON.stringify(d);
const b=new Set(before.map(key)),a=new Set(after.map(key));
const result={reference,baseline:before.length,final:after.length,added:after.filter(d=>!b.has(key(d))),removed:before.filter(d=>!a.has(key(d)))};
writeFileSync(resolve(directory,'typecheck.json'),JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify(result));
